// WIREFRAME: a grid of lines drawn over the surface.
// STATIC (no t): the grid is fixed to the object, not animated.
// In scope: pModel, n_model, viewDir_model, and the constants A-F/S.

// DENSITY comes from the F slider (Constants dock): raise F for a finer
// mesh, lower it for a coarser one. max() keeps the grid from collapsing
// if F is left at 0.
float DENSITY = 12.0 * max(F, 0.05);   // slider F

vec3 p = pModel * DENSITY;

// Distance to the nearest grid plane on each axis, divided by fwidth:
// this holds the lines at about one pixel whatever the zoom, instead of
// letting them thicken up close and alias away in the distance.
vec3 grid = abs(fract(p - 0.5) - 0.5) / fwidth(p);

// min() over the three axes: a point belongs to the wireframe when it is
// close to a grid plane in ANY of the three directions.
float line = min(min(grid.x, grid.y), grid.z);
float wire = 1.0 - min(line, 1.0);

// Background = u_col2, wireframe lines = u_col1 (dock colors).
// With u_col1 set to a bright colour on a dark u_col2 this gives the
// neon-grid look.
textureCol = mix(ubuf.u_col2, ubuf.u_col1, wire);
